input.new_string:
section { padding: 16px 0; border-bottom: 1px solid var(--panel-border); width: 900px; margin: 0 auto; }
.label {
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin: 0 16px 8px;
}
.callout {
  background: rgba(255,95,109,0.08);
  border: 1px solid rgba(255,95,109,0.35);
  border-radius: 8px;
  padding: 10px 12px;
  color: var(--text-dim);
  font-size: 12px;
  margin: 0 16px 12px;
}
.ok {
  background: rgba(61,220,151,0.08);
  border: 1px solid rgba(61,220,151,0.35);
}
.strip {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding: 8px 12px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  min-height: 33px;
  width: calc(100% - 32px);
  margin: 0 16px;
  max-width: 868px;
}

