input.new_string:
.hint {
  margin: 10px 16px 0;
  padding: 8px 10px;
  background: #1a1f29;
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  color: var(--text-dim);
  font-size: 12px;
  max-width: 420px;
}
.meta { margin: 8px 16px 0; color: var(--text-dim); font-size: 12px; }

input.old_string:
.hint {
  margin-top: 10px;
  padding: 8px 10px;
  background: #1a1f29;
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  color: var(--text-dim);
  font-size: 12px;
  max-width: 420px;
}
.meta { margin-top: 8px; color: var(--text-dim); font-size: 12px; }
